  function chord(radius, distance) {
    if (!(radius > 0) || !(distance >= 0)) throw new RangeError('半径须为正数，圆心距须非负');
    if (distance === 0) return { relation: 'coincident', length: null };
    if (distance > 2 * radius) return { relation: 'separate', length: null };
    if (distance === 2 * radius) return { relation: 'tangent', length: 0 };
    return { relation: 'intersect', length: 2 * Math.sqrt(radius * radius - distance * distance / 4) };
  }
